    *,
    narrow: Json[list[NarrowParameter] | None] = None,
) -> HttpResponse:
    if settings.TOPIC_SUMMARIZATION_MODEL is None:  # nocoverage
        raise JsonableError(_("AI features are not enabled on this server."))

    if not user_profile.can_summarize_topics():
        raise JsonableError(_("Insufficient permission"))

    if settings.MAX_PER_USER_MONTHLY_AI_COST is not None:
        used_credits = COUNT_STATS["ai_credit_usage::day"].current_month_accumulated_count_for_user(
            user_profile
        )
        if used_credits >= settings.MAX_PER_USER_MONTHLY_AI_COST * 1000000000:
            raise JsonableError(_("Reached monthly limit for AI credits."))

    summary = do_summarize_narrow(user_profile, narrow)
    if summary is None:  # nocoverage
        raise JsonableError(_("No messages in conversation to summarize"))

    return json_success(request, {"summary": summary})

    def can_summarize_topics(self) -> bool:
        return self.has_permission("can_summarize_topics_group")

    def has_permission(self, policy_name: str, realm: Optional["Realm"] = None) -> bool:
        from zerver.lib.user_groups import user_has_permission_for_group_setting
        from zerver.models import Realm

        if policy_name not in Realm.REALM_PERMISSION_GROUP_SETTINGS:
            raise AssertionError("Invalid policy")

        if realm is None:
            # realm is passed by the caller only when we optimize
            # the number of database queries by fetching the group
            # setting fields using select_related.
            realm = self.realm
        allowed_user_group_id = getattr(realm, policy_name).id
        setting_config = Realm.REALM_PERMISSION_GROUP_SETTINGS[policy_name]
        return user_has_permission_for_group_setting(allowed_user_group_id, self, setting_config)

